sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 */
function handler({api, event, helpers, imports}) {
    // Get roles from the session context

    const userRoles = api.context.session.user.roles || [];

    // IMPORTANT: Replace these with the EXACT 'Name' from the Roles table
    const adminRole = 'admin';
    const studentRole = 'student'; // Change to full name if it has a prefix
    const alumniRole = 'alumni';   // Change to full name if it has a prefix

    console.log('User Roles found:', userRoles); // This helps you debug in F12 console

    if (userRoles.includes(adminRole)) {
        helpers.navigate.to('/x/1909965/admin-portal/admin-dashboard');
    } else if (userRoles.includes(studentRole)) {
        helpers.navigate.to('/x/1909965/almaconnect/student-dashboard');
    } else if (userRoles.includes(alumniRole)) {
        helpers.navigate.to('/x/1909965/alumni-portal/dashboard');
    } else {
        // If roles aren't loading fast enough, we can force a redirect to a general landing
        helpers.navigate.to('/x/1909965/almaconnect/home');
    }

}
